; F1 (SCM0/1, TMC0/1, DMAC0, INTM and four IC registers written every value). Generated by validation/v35s/onchip.py emit: the
; image also preloads the vector stubs and the data in onchip.py.
    BR main
handler:                ; 0103h: AL = the vector (from the stub)
    MOV BL, AL
    XOR AW, AW
    MOV DS0, AW
    MOV [7E00h], BL
    MOV BP, SP
    MOV AW, [BP]
    MOV [7E02h], AW
    MOV AW, [BP+2]
    MOV [7E04h], AW
    MOV AW, [BP+4]
    MOV [7E06h], AW
    MOV [7E08h], SP
    MOV AH, 02h         ; BRKI = 1: the OUT below does not trap
    MOV PSW, AH
    MOV DW, 0FF02h
    OUT DW, AL
    HALT
hspin:
    BR hspin
main:
    XOR AW, AW
    MOV SS, AW
    MOV SP, 7FFEh
    DI

    MOV AW, 0F000h
    MOV DS1, AW
    MOV AW, 0800h
    MOV DS0, AW
    ; 68 SCM0
    DB 26h
    MOV DL, [0FF68h]
    MOV BW, 0FF68h
    MOV IY, 0000h
    MOV CW, 0100h
    XOR AL, AL
